201:    await new Promise<void>((resolve) => setTimeout(resolve, 0));
202:
203:    let download: WebDavBackupPlainResult | null = null;
204:    
205:    try {
206:      // Step 1: Download backup from cloud
207:      download = await this.runWithTimeout(() => this.webdavManager.downloadBackupPlain(false), this.OPERATION_TIMEOUT);
208:      
209:      if (!download.result.success) {
210:        this.webdavBackupResult = `⚠️ ${download.result.message}：${download.result.detail}`;
211:        promptAction.showToast({ message: download.result.message, duration: 1200 });
212:        this.webdavBusy = false;
213:        this.restoreDialogShowing = false;
214:        return;
215:      }
216:      
217:      if (download.plain.length === 0) {
218:        this.webdavBackupResult = '⚠️ 云端无备份：未找到可用的备份文件';
